command:
set -euo pipefail
cd /tmp

echo "== verify staged inputs against their pinned sha256 (the exact bytes bwa aligned) =="
{ printf '%s  %s\n' 61eba5b05ef7d9ae5310e756c1143fa48072de3856d36871bb14e57aa2435ff3 chr20.fa
  printf '%s  %s\n' 4bd24cdfa4486964f070e69b5dd109b6e1e78561783d48c4e62cc6fae3536a00 HG00096_chr20smoke_1.fq.gz
  printf '%s  %s\n' ebd1ad56bc572a4bf157ba21d1ad8ef074ea25f02eb2d982d9f0089180d82a04 HG00096_chr20smoke_2.fq.gz
} > pins.sha256
sha256sum -c pins.sha256

echo "== minimap2 short-read alignment (-ax sr), 400k pairs vs chr20 =="
minimap2 -ax sr -t 4 chr20.fa HG00096_chr20smoke_1.fq.gz HG00096_chr20smoke_2.fq.gz > mm.sam 2> minimap2.log

# The cross-code check reads bwa's staged SAM (bwa_aln.sam = runs/bwa-samtools/r1/aln.sam).
# It is a staged input owned by the instance user; NEVER rm it (sticky /tmp -> EPERM,
# which `rm -f` does not suppress and would kill the task under set -e).
echo "== minimap2 vs bwa concordance, gated on confident (MAPQ>=30) placements in BOTH =="
read MMP MMM MMHI COHI SAMEHI CONC BWATOT < <(awk '
  function prim(f){ return (int(f/256)%2==0 && int(f/2048)%2==0) }
  function unmapped(f){ return (int(f/4)%2==1) }
  function mate(f){ return (int(f/64)%2==1)?1:2 }
  FNR==NR{ if($0~/^@/)next; if(!prim($2))next; bt++; k=$1"\t"mate($2);
           if(!unmapped($2)){ bpos[k]=$3":"$4; bq[k]=$5 } next }
  { if($0~/^@/)next; if(!prim($2))next; mmP++; k=$1"\t"mate($2);
    if(!unmapped($2)){ mmM++; if($5>=30)mmHi++;
      if((k in bpos) && bq[k]>=30 && $5>=30){ coHi++; split(bpos[k],a,":");
        if(a[1]==$3){ d=a[2]-$4; if(d<0)d=-d; if(d<=5) sameHi++ } } }
  }
  END{ printf "%d %d %d %d %d %.4f %d\n", mmP,mmM,mmHi,coHi,sameHi,(coHi>0?sameHi/coHi:0),bt }
' bwa_aln.sam mm.sam)

{
  echo "bwa_reference_primary   $BWATOT   want 800000    (bwa staged aln.sam; same 400k pairs)"
  echo "minimap2_primary        $MMP      want 800000    (400k pairs x2, one primary line each)"
  echo "minimap2_mapped          $MMM     want 100000..250000  (observed 169183; sensitivity, not asserted equal to bwa)"
  echo "minimap2_mapq30          $MMHI    want 10000..40000    (observed 21990)"
  echo "both_confident           $COHI    want > 10000         (observed 20051; the concordance denominator)"
  echo "confident_concordance    $CONC    want >= 0.98         (observed 0.9921)"
} > smoke-check.txt
cat smoke-check.txt

test "$BWATOT" -eq 800000
test "$MMP"    -eq 800000
test "$MMM"    -ge 100000; test "$MMM" -le 250000
test "$MMHI"   -ge 10000;  test "$MMHI" -le 40000
test "$COHI"   -gt 10000
awk -v c="$CONC" 'BEGIN{ if(c>=0.98) exit 0; print "concordance "c" below 0.98"; exit 1 }'
echo "SMOKE CHECK PASSED"
